/* ── 3D Gaming Room Model Extracted from Sketchfab (scene.gltf) ── */
/* Format: Stride 32 (pos: 3, norm: 3, uv: 2), Indexed Triangles */

export interface RoomModelPart {
  id: string;
  color: [number, number, number];
  emissive: number;
  textureUrl?: string;
  verts: Float32Array;
  indices: Uint16Array;
}

function decodeF32(b64: string): Float32Array {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return new Float32Array(bytes.buffer, bytes.byteOffset, len >> 2);
}

function decodeU16(b64: string): Uint16Array {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return new Uint16Array(bytes.buffer, bytes.byteOffset, len >> 1);
}

function makeWallQuad(
  v0: [number, number, number], v1: [number, number, number],
  v2: [number, number, number], v3: [number, number, number],
  u0: [number, number], u1: [number, number],
  u2: [number, number], u3: [number, number],
  normal: [number, number, number],
  cols = 4, rows = 4
): { verts: Float32Array; indices: Uint16Array } {
  const verts: number[] = [];
  for (let j = 0; j <= rows; j++) {
    const t = j / rows;
    for (let i = 0; i <= cols; i++) {
      const s = i / cols;
      const w0 = (1 - s) * (1 - t);
      const w1 = s * (1 - t);
      const w2 = s * t;
      const w3 = (1 - s) * t;

      const x = w0 * v0[0] + w1 * v1[0] + w2 * v2[0] + w3 * v3[0];
      const y = w0 * v0[1] + w1 * v1[1] + w2 * v2[1] + w3 * v3[1];
      const z = w0 * v0[2] + w1 * v1[2] + w2 * v2[2] + w3 * v3[2];

      const u = w0 * u0[0] + w1 * u1[0] + w2 * u2[0] + w3 * u3[0];
      const v = w0 * u0[1] + w1 * u1[1] + w2 * u2[1] + w3 * u3[1];

      verts.push(x, y, z, normal[0], normal[1], normal[2], u, v);
    }
  }

  const indices: number[] = [];
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const p0 = j * (cols + 1) + i;
      const p1 = p0 + 1;
      const p2 = (j + 1) * (cols + 1) + i;
      const p3 = p2 + 1;
      indices.push(p0, p1, p3, p0, p3, p2);
    }
  }

  return {
    verts: new Float32Array(verts),
    indices: new Uint16Array(indices),
  };
}

